/** @jsxImportSource solid-js */
import { onMount, onCleanup, createEffect } from "solid-js";
import { mountGalaxyEffortSlider, type GalaxyEffortSliderOptions } from "../../components/galaxy-effort-slider/GalaxyEffortSliderEngine.js";
import type { MotionController } from "../../components/galaxy-effort-slider/motion-runtime";

export function GalaxyEffortSlider(props: { options?: GalaxyEffortSliderOptions; class?: string }) {
  let host!: HTMLDivElement;
  let controller: MotionController | undefined;
  onMount(() => { controller = mountGalaxyEffortSlider(host, props.options); });
  createEffect(() => { const options = props.options; controller?.update(options ?? {}); });
  onCleanup(() => controller?.destroy());
  return <div ref={host} class={props.class} data-motion-component="galaxy-effort-slider" />;
}

